#include <bits/stdc++.h>
using namespace std;
const int MAX_SIZE = 250005;
int total, maxKVal, modVal;
using LL = long long;

LL binPow(LL base, LL exp) {
    LL res = 1;
    while (exp > 0) {
        if (exp & 1) res = res * base % modVal;
        base = base * base % modVal;
        exp >>= 1;
    }
    return res;
}

inline int getBit(int x) {
    return x & (-x);
}

LL factArr[MAX_SIZE], invFactArr[MAX_SIZE], dpCache[26][MAX_SIZE];

LL recurseDP(int level, int mask) {
    if (dpCache[level][mask] != -1) return dpCache[level][mask];
    if (mask == 0) {
        dpCache[level][mask] = factArr[total];
        for (int i = 1; i <= level; i++)
            dpCache[level][mask] = dpCache[level][mask] * (maxKVal - i + 1) % modVal;
        return dpCache[level][mask];
    }
    LL &res = dpCache[level][mask];
    res = 0;
    int tmp_mask = mask - getBit(mask);
    for (int sub_mask = tmp_mask; sub_mask > 0; sub_mask = (sub_mask - 1) & tmp_mask)
        res = (res + invFactArr[mask - sub_mask] * recurseDP(level + 1, sub_mask)) % modVal;
    res = (res + invFactArr[mask] * recurseDP(level + 1, 0)) % modVal;
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> total >> maxKVal >> modVal;
    LL answer = binPow(maxKVal, total);
    if (total & 1) {
        cout << answer << "\n";
        return 0;
    }
    factArr[0] = 1;
    for (int i = 1; i <= total; i++) factArr[i] = factArr[i - 1] * i % modVal;
    invFactArr[total] = binPow(factArr[total], modVal - 2);
    for (int i = total; i > 0; --i) invFactArr[i - 1] = invFactArr[i] * i % modVal;
    memset(dpCache, -1, sizeof(dpCache));
    answer = (answer - recurseDP(0, total) + modVal) % modVal;
    cout << answer << "\n";
    return 0;
}
